import React, { useState, useEffect, useContext } from 'react';
import { AppContext } from '../../App';
import { useApplications } from '../../hooks/useApplications';
import { FileText, CheckCircle2, XCircle, Clock, Search, Filter, ChevronRight, Briefcase, Building2, User } from 'lucide-react';
import { Link } from 'react-router-dom';

const Applications = () => {
  const { user, userType } = useContext(AppContext);
  const { getAllApplications, getApplicationsByStudent, updateApplicationStatus, loading: applicationsLoading } = useApplications();

  const [applications, setApplications] = useState([]);
  const [loading, setLoading] = useState(true);
  const [filter, setFilter] = useState('all');
  const [searchTerm, setSearchTerm] = useState('');

  useEffect(() => {
    loadApplications();
  }, [userType, user]);

  const loadApplications = async () => {
    try {
      setLoading(true);
      let appsData;
      if (userType === 'admin') {
        appsData = await getAllApplications();
      } else if (userType === 'student') {
        appsData = await getApplicationsByStudent(user.id);
      } else {
        // Employers see apps for their jobs (this would usually be filtered by backend, 
        // but here we get all and filter if backend doesn't handle specific employer apps)
        appsData = await getAllApplications();
        // Since we don't have getByEmployerId, we might need to filter by job owner
        // For now, let's assume getAll handles it or we'll filter here if job data is attached
      }
      setApplications(appsData.sort((a, b) => new Date(b.applicationDate) - new Date(a.applicationDate)));
    } catch (error) {
      console.error('Failed to load applications:', error);
    } finally {
      setLoading(false);
    }
  };

  const getStatusBadge = (status) => {
    const statusConfig = {
      'under_review': { bg: 'bg-charcoal-500/10', text: 'text-charcoal-600', border: 'border-charcoal-500/20' },
      'shortlisted': { bg: 'bg-blue-600/10', text: 'text-blue-600', border: 'border-blue-600/20' },
      'accepted': { bg: 'bg-emerald-600/10', text: 'text-emerald-600', border: 'border-emerald-600/20' },
      'rejected': { bg: 'bg-rose-600/10', text: 'text-rose-600', border: 'border-rose-600/20' }
    };

    const config = statusConfig[status] || { bg: 'bg-charcoal-400/10', text: 'text-charcoal-400', border: 'border-charcoal-400/20' };
    return (
      <span className={`px-3 py-1 rounded-full text-[10px] font-nexed font-black border tracking-widest uppercase ${config.bg} ${config.text} ${config.border}`}>
        {status.replace('_', ' ')}
      </span>
    );
  };

  const filteredApps = applications.filter(app => {
    const matchesFilter = filter === 'all' || app.status === filter;
    const matchesSearch = 
      app.jobTitle.toLowerCase().includes(searchTerm.toLowerCase()) ||
      app.company.toLowerCase().includes(searchTerm.toLowerCase()) ||
      (app.studentName && app.studentName.toLowerCase().includes(searchTerm.toLowerCase()));
    return matchesFilter && matchesSearch;
  });

  if (loading) {
    return (
      <div className="min-h-screen bg-background flex items-center justify-center">
        <div className="w-12 h-12 border-4 border-charcoal-100 border-t-charcoal-800 rounded-full animate-spin"></div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-background pb-24 font-sans text-charcoal-800">
      {/* Cinematic Header */}
      <div className="h-64 bg-white relative overflow-hidden border-b border-charcoal-50">
        <div className="absolute inset-0 bg-charcoal-gradient opacity-[0.02]"></div>
        <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-[1000px] h-[1000px] bg-charcoal-800/5 rounded-full blur-[150px]"></div>

        <div className="max-w-7xl mx-auto px-4 h-full flex flex-col justify-center relative z-10">
          <div className="flex flex-col md:flex-row md:items-end justify-between gap-8">
            <div>
              <h1 className="text-4xl md:text-6xl font-nexed font-bold text-charcoal-900 tracking-tight leading-none mb-4">Application Hub</h1>
              <p className="text-charcoal-500 text-lg font-light tracking-wide italic">Tracking career trajectories and talent acquisitions.</p>
            </div>
            <div className="flex items-center gap-4">
               <div className="bg-charcoal-50 p-1.5 rounded-2xl border border-charcoal-100 flex items-center shadow-sm">
                  <div className="w-10 h-10 bg-white rounded-xl flex items-center justify-center text-charcoal-800 border border-charcoal-100">
                     <FileText size={20} />
                  </div>
                  <div className="px-4">
                     <p className="text-[10px] font-nexed font-black text-charcoal-400 uppercase tracking-widest leading-none mb-1">Total Records</p>
                     <p className="text-xl font-nexed font-bold text-charcoal-900 leading-none">{applications.length}</p>
                  </div>
               </div>
            </div>
          </div>
        </div>
      </div>

      <div className="max-w-7xl mx-auto px-4 -mt-12 relative z-20">

        {/* Controls Bar */}
        <div className="bg-white/80 backdrop-blur-xl rounded-[2.5rem] border border-charcoal-100 p-4 mb-10 flex flex-col md:flex-row gap-6 shadow-xl items-center">
          <div className="flex-1 relative w-full">
            <Search className="absolute left-6 top-1/2 -translate-y-1/2 text-charcoal-300" size={20} />
            <input 
              type="text" 
              placeholder="Search by role, company or talent..."
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="w-full bg-charcoal-50 border-none rounded-2xl py-4 pl-16 pr-6 text-charcoal-900 placeholder:text-charcoal-300 focus:ring-2 focus:ring-charcoal-100 transition-all font-nexed"
            />
          </div>

          <div className="flex gap-2 p-1.5 bg-charcoal-50 rounded-[1.5rem] border border-charcoal-100 w-full md:w-auto overflow-x-auto">
            {['all', 'under_review', 'shortlisted', 'accepted', 'rejected'].map(s => (
              <button
                key={s}
                onClick={() => setFilter(s)}
                className={`px-6 py-2.5 rounded-xl text-[10px] font-nexed font-black uppercase tracking-widest transition-all whitespace-nowrap ${filter === s ? 'bg-black text-white shadow-lg' : 'text-charcoal-500 hover:text-charcoal-800'}`}
              >
                {s.replace('_', ' ')}
              </button>
            ))}
          </div>
        </div>

        {/* Applications Feed */}
        {filteredApps.length > 0 ? (
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
            {filteredApps.map(app => (
              <div key={app.id} className="bg-white rounded-[3rem] border border-charcoal-100 p-8 hover:border-charcoal-300 transition-all duration-500 group shadow-sm hover:shadow-xl relative overflow-hidden">
                <div className="flex justify-between items-start mb-8">
                  <div className="flex items-center gap-5">
                    <div className="w-16 h-16 bg-charcoal-50 rounded-2xl flex items-center justify-center text-charcoal-800 border border-charcoal-100 shadow-sm">
                      {userType === 'student' ? <Building2 size={28} /> : <User size={28} />}
                    </div>
                    <div>
                      <h3 className="text-2xl font-nexed font-bold text-charcoal-900 mb-1">{app.jobTitle}</h3>
                      <p className="text-charcoal-500 font-light italic flex items-center gap-2">
                        {userType === 'student' ? app.company : app.studentName}
                      </p>
                    </div>
                  </div>
                  {getStatusBadge(app.status)}
                </div>

                <div className="space-y-4 mb-10">
                   <div className="flex items-center gap-4 text-charcoal-400 text-[10px] font-nexed font-black uppercase tracking-widest">
                      <div className="flex items-center gap-2 px-3 py-1 bg-charcoal-50 rounded-lg border border-charcoal-100">
                        <Clock size={12} /> Applied {new Date(app.applicationDate).toLocaleDateString()}
                      </div>
                      <div className="flex items-center gap-2 px-3 py-1 bg-charcoal-50 rounded-lg border border-charcoal-100">
                        ID: {app.id.slice(-8).toUpperCase()}
                      </div>
                   </div>
                   <p className="text-charcoal-600 text-sm line-clamp-2 italic leading-relaxed">
                      "{app.coverLetter}"
                   </p>
                </div>

                <div className="flex items-center justify-between pt-8 border-t border-charcoal-50">
                   <Link 
                     to={`/job/${app.jobId}`}
                     className="text-[10px] font-nexed font-black text-charcoal-400 uppercase tracking-[0.2em] hover:text-charcoal-900 transition-colors flex items-center gap-2 group/link"
                   >
                     View Mandate Details <ChevronRight size={14} className="group-hover/link:translate-x-1 transition-transform" />
                   </Link>

                   <div className="flex gap-3">
                      {(userType === 'employer' || userType === 'admin') && app.status === 'under_review' && (
                        <>
                          <button 
                            onClick={() => updateApplicationStatus(app.id, 'shortlisted')}
                            className="bg-charcoal-50 text-charcoal-800 px-5 py-2.5 rounded-xl text-[10px] font-nexed font-black uppercase tracking-widest hover:bg-charcoal-900 hover:text-white transition-all border border-charcoal-100"
                          >
                            Shortlist
                          </button>
                        </>
                      )}
                      <button className="w-10 h-10 rounded-xl bg-charcoal-50 flex items-center justify-center text-charcoal-300 hover:text-charcoal-900 border border-charcoal-100 transition-all">
                        <Filter size={18} />
                      </button>
                   </div>
                </div>
              </div>
            ))}
          </div>
        ) : (
          <div className="py-40 bg-white rounded-[4rem] border border-charcoal-100 text-center shadow-sm">
            <div className="w-24 h-24 bg-charcoal-50 rounded-3xl flex items-center justify-center mx-auto mb-8 border border-charcoal-100">
              <FileText className="text-charcoal-200" size={40} />
            </div>
            <h4 className="text-3xl font-nexed font-bold text-charcoal-900 mb-3">No Records Found</h4>
            <p className="text-charcoal-500 font-light italic max-w-sm mx-auto">
              Your search parameters yielded no intelligence results in the current hub.
            </p>
          </div>
        )}
      </div>
    </div>
  );
};

export default Applications;
